/**
 * V3 portfolio router.
 *
 * This is deliberately local and deterministic: feature extraction, eligibility
 * checks and scoring read only request data plus the in-process model registry.
 * It is therefore safe for the hot path and provides a stable baseline for the
 * RouterBench evaluation before health telemetry / an optional judge are added.
 */

import { DEFAULT_ROUTING_CONFIG } from "./config.js";
import { DEFAULT_MODEL_CAPABILITIES } from "./model-capabilities.js";
import { getFallbackChain, selectModel, usablePricing } from "./selector.js";
import { RulesStrategy } from "./strategy.js";
import {
  HISTORICAL_MODEL_PROFILES,
  LIVE_MODEL_PROFILES,
  type ModelPerformanceProfile,
} from "./model-profiles.js";
import type { RouterOptions, RouterStrategy, TaskType, Tier, TierConfig } from "./types.js";
import { inferToolRequirement } from "./tool-intent.js";
import { estimateTokens, sampleForScan, scanLimit } from "./tokens.js";

type TaskFeatures = {
  taskType: TaskType;
  estimatedInputTokens: number;
  hasCode: boolean;
  needsTools: boolean;
  toolsAvailable: boolean;
  needsVision: boolean;
  needsStructuredOutput: boolean;
  latencySensitive: boolean;
  highStakes: boolean;
  language: "zh" | "other";
  likelyParallelToolCalls: boolean;
  complexMultiToolPlan: boolean;
  agentDomain: "airline" | "retail" | "web_research" | "other";
  deepWebResearch: boolean;
  agentRisk: "standard" | "high" | "complex_high" | "policy_exception_simple" | "policy_exception";
  terminalToolSignal: boolean;
  terminalSafetySensitive: boolean;
  implicitTerminalCode: boolean;
  /** A code artifact or coding action is present, not merely a language name. */
  codeArtifact: boolean;
};

// The bundled config carries the calibrated weights; a host config that omits
// `portfolio` scores with the same numbers rather than a second copy of them.
const DEFAULT_PORTFOLIO_WEIGHTS = DEFAULT_ROUTING_CONFIG.portfolio!;

/**
 * Detect turns that probably need several tool calls. This is a
 * deliberately conservative request-side feature: it uses only the prompt
 * and visible tool count, never benchmark categories or expected answers.
 */
function likelyNeedsParallelToolCalls(
  prompt: string,
  needsTools: boolean,
  toolCount: number | undefined,
  toolNames: readonly string[] | undefined,
): boolean {
  if (!needsTools || toolCount === undefined || toolCount < 1) return false;
  const text = prompt.trim();
  const explicitRepeat =
    /\b(?:in parallel|simultaneously|concurrently|for each|each of|every one|both|(?:two|three|multiple|several)\s+(?:cities|locations|items|tasks|orders|users|files))\b|并行|同时|分别|每个|各自|(?:两个|三个|多个)(?:城市|地点|项目|任务|订单|用户|文件)|cada uno|para cada|simult[aá]neamente/i.test(
      text,
    );
  if (explicitRepeat) return true;

  const sentenceClauses = text
    .split(/[.!?。！？]+/)
    .map((part) => part.trim())
    .filter((part) => part.length >= 8);
  if (
    (/\b(?:also|additionally|furthermore)\b|另外|此外|그리고/i.test(text) &&
      sentenceClauses.length >= 2) ||
    /\band\s+(?:also|for the)\b/i.test(text)
  )
    return true;

  const pairedQuantity =
    /\b\d+(?:\.\d+)?\s+(?:and|or)\s+\d+(?:\.\d+)?\s*(?:gb|mb|tb|kg|g|ml|oz|cups?|cores?|cpus?)\b/i.test(
      text,
    );
  if (pairedQuantity) return true;

  // Distinctive tokens from two visible tool names are a strong local signal
  // for a multi-operation turn (for example add_task + delete_task).
  const operationTokens = new Set([
    "add",
    "delete",
    "remove",
    "cancel",
    "return",
    "exchange",
    "modify",
    "book",
    "transfer",
    "send",
    "upload",
    "download",
    "create",
    "close",
  ]);
  // Whole words only, with an optional inflection: a substring test read
  // "add" out of "address", "book" out of "facebook" and "close" out of
  // "closet" (the same failure rules.ts fixed for its keyword lists).
  const lowered = text.toLowerCase();
  const matchedOperationTokens = new Set(
    (toolNames ?? [])
      .flatMap((name) => name.toLowerCase().split(/[^a-z0-9\u3400-\u9fff]+/))
      .filter(
        (token) =>
          operationTokens.has(token) &&
          new RegExp(`\\b${token}(?:s|es|d|ed|ing)?\\b`).test(lowered),
      ),
  );
  // A single workflow naturally mentions domain nouns like order/item plus
  // one action. Upgrade only when two different visible operation verbs are
  // requested (for example cancel + book or add + delete).
  if (matchedOperationTokens.size >= 2) return true;

  // Repeated food/logging entries are commonly expressed as several lines,
  // each with its own quantity rather than an explicit "for each" phrase.
  const nonEmptyLines = text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const quantityMentions =
    text.match(
      /\b(?:\d+(?:\.\d+)?|one|two|three|four|five|six|seven|eight|nine|ten)\s*(?:oz|ounce|ounces|g|gram|grams|kg|ml|cups?|pieces?|tablespoons?)\b/gi,
    ) ?? [];
  if (nonEmptyLines.length >= 2 && quantityMentions.length >= 2) return true;

  // Weather prompts provide a useful language-independent high-confidence
  // pattern: a single lookup tool plus multiple locations joined in one turn.
  const repeatedLookup =
    /\b(?:weather|climate|clima|tiempo|temperature|snow|news|report)\b|天气|气象|温度|降雪|新闻|报告/i.test(
      text,
    );
  const multiLocationConnector =
    /\b(?:and also|both)\b|\s(?:y|e)\s|还有|以及|和|、/i.test(text);
  const commaSeparatedLocations = (text.match(/[,，]/g) ?? []).length >= 2;
  if (repeatedLookup && (multiLocationConnector || commaSeparatedLocations)) return true;

  const distinctOrderParts =
    /\b(?:food|meal)\b[\s\S]*\bdrink\b|\bdrink\b[\s\S]*\b(?:food|meal)\b/i.test(text);
  const koreanParallelClauses = (text.match(/,/g) ?? []).length >= 3 && /하고|그리고/.test(text);
  return distinctOrderParts || koreanParallelClauses;
}

function classifyTask(
  prompt: string,
  systemPrompt: string | undefined,
  options: RouterOptions,
): TaskFeatures {
  const fullText = `${systemPrompt ?? ""} ${prompt}`;
  const estimatedInputTokens = estimateTokens(fullText);
  const limit = scanLimit(options.config.classifier.promptTruncationChars);
  const scannedPrompt = sampleForScan(prompt, limit);
  const scannedSystemPrompt = sampleForScan(systemPrompt ?? "", limit);
  // Only the deep-web-research clue detectors below read the system prompt,
  // and they are gated on a web-research tool surface. Every other feature
  // reads the user turn: a host's standing instructions ("be quick", "follow
  // security best practices", a Mandarin persona) describe the assistant, not
  // this request, and must not move its scoring or language band.
  const scannedFullText = `${scannedSystemPrompt} ${scannedPrompt}`;
  const text = scannedPrompt.toLowerCase();
  const explicitCodeSignal =
    /```|\b(?:typescript|javascript|python|rust|java|sql|stack trace|traceback|exception)\b|\.(?:ts|tsx|js|py|go|rs)\b/i.test(
      scannedPrompt,
    );
  // `class` is common in non-code Agent domains (for example airline cabin
  // class). Treat code constructs as code only when the prompt also contains
  // an implementation/editing cue, instead of letting a single ambiguous
  // noun redirect an entire tool session to the code-agent portfolio.
  const codeConstructSignal =
    /\b(?:implement|refactor|debug|write|edit|modify|create|define|review|fix)\b[\s\S]{0,48}\b(?:api|function|class|method)\b|\b(?:api|function|class|method)\b[\s\S]{0,48}\b(?:code|implementation|typescript|javascript|python|rust|java)\b/i.test(
      scannedPrompt,
    );
  const nativeCodeSignal =
    /\b(?:programmed|written|implemented?|code)\s+(?:in|using)\s+(?:c\+\+|c|rust|go)\b/i.test(
      scannedPrompt,
    );
  // A CamelCase error class (TypeError, NullPointerException) is a runtime
  // artifact, not prose about errors; case-sensitive on purpose.
  const errorClassSignal = /\b[A-Z][A-Za-z]*(?:Error|Exception)\b/.test(scannedPrompt);
  const hasCode = explicitCodeSignal || codeConstructSignal || nativeCodeSignal || errorClassSignal;
  // A language name alone ("java coffee prices", "python snake habitat") is
  // not code work, even on a tool turn. It joins the code-agent pool only
  // together with a coding action.
  const codingAction =
    /\b(?:write|implement|refactor|debug|fix|patch|compile|build|run|test|script|program|code|function|class|module|repo(?:sitory)?)\b|编写|实现|重构|调试|修复|编译|脚本|代码/i.test(
      scannedPrompt,
    );
  // Stronger than hasCode: an actual code artifact or coding action, never a
  // bare language name ("What is Python?" is trivia, not a code task) and
  // never the English word "exception" on its own ("please make an
  // exception"); a thrown exception shows up as a CamelCase class above.
  const codeArtifact =
    /```|\b(?:stack trace|traceback)\b|\.(?:ts|tsx|js|py|go|rs)\b/i.test(scannedPrompt) ||
    codeConstructSignal ||
    nativeCodeSignal ||
    errorClassSignal;
  const toolsAvailable = options.hasTools ?? false;
  const needsTools =
    options.requiresTools ??
    (toolsAvailable && inferToolRequirement(scannedPrompt, scannedSystemPrompt));
  const likelyParallelToolCalls = likelyNeedsParallelToolCalls(
    scannedPrompt,
    needsTools,
    options.toolCount,
    options.toolNames,
  );
  const normalizedToolNames = (options.toolNames ?? []).map((name) => name.toLowerCase());
  const airlineToolSignal = normalizedToolNames.some((name) =>
    /(?:flight|reservation|airport|baggage|passenger)/.test(name),
  );
  const retailToolSignal = normalizedToolNames.some((name) =>
    /(?:order|product|item|return|exchange|address)/.test(name),
  );
  const webResearchToolSignal = normalizedToolNames.some((name) =>
    /^(?:web_?search|web_?fetch)$/.test(name),
  );
  const agentDomain =
    airlineToolSignal && !retailToolSignal
      ? "airline"
      : retailToolSignal && !airlineToolSignal
        ? "retail"
        : webResearchToolSignal
          ? "web_research"
          : "other";
  // Distinguish a cheap lookup from a BrowseComp-like investigation. These
  // prompts require joining several clues, resolving an entity, and ending in
  // one exact answer; complete agent trajectories show that treating them as
  // ordinary search causes long, costly loops. This is request/tool-surface
  // evidence only and does not depend on a benchmark id or hidden answer.
  const clueConnectors =
    scannedFullText.match(
      /\b(?:after|before|while|where|whose|which|in \d{4}|as of|over \d+|another|also|furthermore)\b|(?:之后|之前|其中|截至|超过|另一个|此外)/gi,
    ) ?? [];
  const entityResolutionSignal =
    /\b(?:identify|who (?:is|was)|what (?:is|was) the name|which (?:person|player|company|country|city)|find the (?:person|player|name|entity))\b|(?:找出|识别|是谁|哪位|名称是什么)/i.test(
      scannedFullText,
    );
  const exactAnswerSignal =
    /\b(?:exact answer|single best-supported answer|following clues|multiple public sources)\b|(?:精确答案|根据.*线索|多个公开来源)/i.test(
      scannedFullText,
    );
  const deepWebResearch =
    agentDomain === "web_research" &&
    (exactAnswerSignal ||
      (entityResolutionSignal && (clueConnectors.length >= 3 || prompt.length >= 320)));
  const globalOptimizationSignal =
    /\b(?:cheapest|lowest[- ]price|least expensive|most expensive|highest(?:[- ]priced)?|largest|smallest|maximum|minimum|best available|closest|not (?:cost|exceed))\b|最便宜|最低价|最贵|最高价|最大|最小/i.test(
      scannedPrompt,
    );
  const globalScopeSignal =
    /\b(?:everything|all (?:(?:my|your|their|the) )?(?:future |upcoming )?(?:items|orders|passengers|flights|reservations|bookings)|every (?:item|order|passenger|flight|reservation|booking))\b|全部|所有|每个/i.test(
      scannedPrompt,
    );
  const globalChoiceSignal = globalOptimizationSignal || globalScopeSignal;
  const crossRecordSignal =
    /\b(?:another|other|different|previous)\s+(?:order|reservation|booking|account|address)\b|另一(?:个)?(?:订单|预订|账户|地址)|其他(?:订单|预订|账户|地址)/i.test(
      scannedPrompt,
    );
  // Reservation locators mix letters and digits (ZFA04Y, 4WQ150). Requiring
  // both keeps shouted words ("CANCEL MY FLIGHT") and plain six-digit numbers
  // from reading as two reservations.
  const reservationIds =
    scannedPrompt.match(/\b(?=[A-Z0-9]*\d)(?=[A-Z0-9]*[A-Z])[A-Z0-9]{6}\b/g) ?? [];
  const crossReservationBatchSignal =
    agentDomain === "airline" &&
    (/\b(?:two|three|multiple|several)(?:\s+of\s+(?:my|our|the))?\s+(?:upcoming\s+)?(?:reservations?|bookings?)\b|\b(?:a\s+)?(?:second|third)\s+(?:reservation|booking)\b/i.test(
      scannedPrompt,
    ) ||
      new Set(reservationIds).size >= 2);
  const conditionalGlobalWorkflowSignal =
    agentDomain === "airline" &&
    globalScopeSignal &&
    /\b(?:if|that (?:contain|have)|longer than|shorter than|under|over|at (?:most|least)|wherever possible)\b|如果|超过|少于|不超过|尽可能/i.test(
      scannedPrompt,
    ) &&
    /\b(?:cancel|change|upgrade|move|book)\b[\s\S]*\b(?:cancel|change|upgrade|move|book)\b|取消[\s\S]*(?:升级|更改)|升级[\s\S]*(?:取消|更改)/i.test(
      scannedPrompt,
    );
  // A refund explicitly targeted at a named/non-original card can conflict
  // with account state and require escalation rather than a substitute action.
  // This narrow feature is visible on the first turn and avoids sending every
  // ordinary return workflow to the expensive policy specialist.
  const policyExceptionSignal =
    agentDomain === "retail" &&
    /\b(?:return|refund|send back|get (?:my |the )?money back)\b|退货|退款|退回/i.test(
      scannedPrompt,
    ) &&
    /\b(?:amex|american express|visa|mastercard|credit card|debit card|different card|another card|other card)\b|信用卡|借记卡|其他卡|另一张卡/i.test(
      scannedPrompt,
    );
  // A comparative selector can mention two products while requesting only
  // one write (for example "send back the pricier one"). Three-repeat tau2
  // calibration found no quality gain from the policy specialist on these
  // single-write cases, so keep them in a distinct, lower-cost risk band.
  const singleSelectedPolicyException =
    policyExceptionSignal &&
    /\b(?:return|refund|send back)\b[^.!?。！？]{0,96}\b(?:the )?(?:pricier|cheaper|more expensive|less expensive|costlier|one)\b/i.test(
      scannedPrompt,
    );
  // Returns and exchanges often pivot after confirmation (return -> rethink
  // -> exchange -> choose a variant). That future state is not visible to a
  // task-start router, so treat the observable workflow verb as the risk cue.
  // Simpler cancellation and one-field order edits stay on the standard path.
  const negotiatedWorkflowSignal =
    agentDomain === "retail" && /\b(?:return|exchange)\b|退货|退回|换货|交换/i.test(scannedPrompt);
  const numberedSteps = (scannedPrompt.match(/(?:^|\s)\d+(?:\.\d+)*[.)]\s+/g) ?? []).length;
  const complexMultiToolPlan =
    likelyParallelToolCalls &&
    ((options.toolCount ?? 0) >= 6 || numberedSteps >= 3 || prompt.length > 1_200);
  let agentRisk: TaskFeatures["agentRisk"] =
    needsTools && singleSelectedPolicyException
      ? "policy_exception_simple"
      : needsTools && policyExceptionSignal
        ? "policy_exception"
        : // Airline prompts that require a global optimum (for example the
          // cheapest itinerary across several candidates) are materially harder
          // than applying one change to every passenger in a known reservation.
          // Full-session evidence supports Sonnet for the former, while upgrading
          // the latter merely because it says "all passengers" caused a large cost
          // increase without a quality gain.
          needsTools &&
            agentDomain === "airline" &&
            (globalOptimizationSignal || conditionalGlobalWorkflowSignal)
          ? "complex_high"
          : needsTools &&
              (likelyParallelToolCalls ||
                globalChoiceSignal ||
                crossRecordSignal ||
                crossReservationBatchSignal ||
                negotiatedWorkflowSignal)
            ? "high"
            : "standard";
  const needsVision = options.hasVision ?? false;
  const needsStructuredOutput = options.requiresStructuredOutput ?? false;
  const latencySensitive =
    /\b(?:urgent|asap|fast|quick|low latency|real[- ]time)\b|尽快|马上|快速|低延迟/i.test(
      scannedPrompt,
    );
  const highStakes =
    /\b(?:production|security|payment|legal|medical|financial|audit)\b|生产|安全|支付|法律|医疗|财务|审计/i.test(
      scannedPrompt,
    );
  // Terminal tasks often describe the desired artifact rather than naming a
  // programming language. Treat only small, deterministic local build/file
  // work as implicit code. Operational deployment, credentials, destructive
  // work, evaluation, vision, and broad search stay on the stronger generic
  // tool-agent path. This is a request-side feature, not a benchmark ID list.
  const terminalToolSignal = normalizedToolNames.some((name) =>
    /^(?:terminalexec|terminalinspect|terminalsendkeys)$/.test(name),
  );
  const simpleTerminalArtifact =
    /\b(?:create|write|convert|generate|build|implement|run|fix|repair|debug|make)\b[\s\S]{0,120}\b(?:file|script|csv|parquet|json|txt|server|endpoint)\b/i.test(
      scannedPrompt,
    );
  // Multi-file repair is qualitatively different from fixing one known local
  // script. The agent must preserve state across inspections, infer ordering
  // and dependencies, edit several artifacts, and close the loop with tests.
  // A frozen Terminal-Bench trajectory showed the economy model spending 27
  // turns repeatedly rereading files without making an edit, while Opus solved
  // the same task in eight turns. Promote this request-visible pattern before
  // model scoring; no benchmark ID or expected answer is consulted.
  const terminalComplexRepair =
    terminalToolSignal &&
    /\b(?:multiple|several)\s+(?:scripts?|files?|components?)\b|\b(?:pipeline|dependencies)\b[\s\S]{0,100}\b(?:fail|issue|fix|repair|run|execute)\b|\b(?:identify|find|fix|repair)\s+(?:and\s+)?(?:fix\s+)?all\s+(?:the\s+)?issues\b/i.test(
      scannedPrompt,
    );
  // One artifact that must be accepted by multiple compilers/runtimes is not
  // a routine file-writing task. It requires reasoning across incompatible
  // grammars and validating every execution path; cheap code models can
  // produce plausible-looking source that satisfies neither toolchain.
  const mentionedTerminalRuntimes = new Set(
    (scannedPrompt.match(/\b(?:gcc|clang|rustc|javac|go\s+build|node|python)\b/gi) ?? []).map(
      (name) => name.toLowerCase().replace(/\s+/g, " "),
    ),
  );
  const terminalCrossRuntimeArtifact =
    terminalToolSignal &&
    (/\bpolyglot\b/i.test(scannedPrompt) ||
      /\b(?:both|each)\b[\s\S]{0,120}\b(?:compilers?|runtimes?|toolchains?)\b/i.test(
        scannedPrompt,
      ) ||
      (mentionedTerminalRuntimes.size >= 2 &&
        /\b(?:compile|build|run|execute)\b/i.test(scannedPrompt)));
  // Framework-to-native ports combine binary checkpoint inspection, weight
  // export, tensor-layout reasoning, image/data decoding, and a separately
  // compiled runtime. A task-start router can see this boundary directly in
  // the request (for example PyTorch state_dict -> a pure C CLI); treating it
  // like routine single-file C work caused a 30-turn read/retry loop in a
  // frozen official Terminal-Bench trajectory.
  const terminalFrameworkToNativeArtifact =
    terminalToolSignal &&
    /\b(?:pytorch|tensorflow|jax|onnx|state[_ -]?dict|checkpoint|safetensors?)\b|\.(?:pth|pt|onnx)\b/i.test(
      scannedPrompt,
    ) &&
    /\b(?:pure|native|programmed|written|implemented?)\s+(?:in|using)\s+(?:c\+\+|c|rust|go)\b|\b(?:c\+\+|c|rust|go)\s+(?:program|binary|executable|cli|tool|implementation)\b/i.test(
      scannedPrompt,
    ) &&
    /\b(?:inference|model|weights?|tensor|export|convert|load)\b/i.test(scannedPrompt);
  if (
    needsTools &&
    (terminalComplexRepair || terminalCrossRuntimeArtifact || terminalFrameworkToNativeArtifact) &&
    (agentRisk === "standard" || agentRisk === "high")
  )
    agentRisk = "complex_high";
  const complexTerminalOperation =
    /\b(?:git|ssh|nginx|https|certificate|authentication|credential|deploy|production|encrypt|gpg|shred|securely delete|decommission|benchmark|evaluate|embedding|chess|image|search the web|schema|statistical|statistics|aggregate|join|multiple inputs?)\b/i.test(
      scannedPrompt,
    );
  // A bare "token" is not a credential signal: blockchain, tokenizer, and
  // LLM tasks use that word routinely (for example "token transfers"). Only
  // treat it as sensitive when the prompt gives it an authentication/secret
  // qualifier. API keys remain an unambiguous high-risk signal on their own.
  const terminalCredentialSignal =
    /\b(?:ssh|nginx|certificate|authentication|credentials?|passwords?|api keys?|deploy|production|encrypt|gpg|shred|securely delete|decommission)\b/i.test(
      scannedPrompt,
    ) ||
    /\b(?:access|auth|authentication|bearer|secret|api)\s+tokens?\b|\btokens?\s+(?:secret|credential|authentication)\b/i.test(
      scannedPrompt,
    );
  const terminalSafetySensitive = terminalToolSignal && (highStakes || terminalCredentialSignal);
  const implicitTerminalCode =
    needsTools &&
    terminalToolSignal &&
    agentRisk === "standard" &&
    !highStakes &&
    !complexTerminalOperation &&
    numberedSteps < 3 &&
    prompt.length <= 1_000 &&
    simpleTerminalArtifact;
  // Han characters alone also spell Japanese; kana marks the prompt as not
  // Mandarin, so it does not get the Mandarin-native extraction band.
  const language =
    /[\u3400-\u9fff]/.test(scannedPrompt) && !/[\u3040-\u30ff]/.test(scannedPrompt)
      ? "zh"
      : "other";
  const multipleChoiceSignals = (scannedPrompt.match(/(?:^|\n)\s*[A-D][.)]\s+/gim) ?? []).length;
  const numericSignals = (scannedPrompt.match(/-?\d+(?:[.,]\d+)?/g) ?? []).length;
  const compactMathProblem =
    !hasCode &&
    prompt.length < 2_500 &&
    numericSignals >= 2 &&
    (/[+×÷=%$€£¥]|\b(?:total|each|per|times|half|twice|percent|how many|how much|calculate)\b/i.test(
      scannedPrompt,
    ) ||
      /[?？]\s*$/.test(scannedPrompt.trim()) ||
      numericSignals >= 3);

  let taskType: TaskType = "chat";
  if (needsVision) taskType = "vision";
  else if (estimatedInputTokens > 80_000) taskType = "long_context";
  else if (needsTools && (codeArtifact || (hasCode && codingAction) || implicitTerminalCode))
    taskType = "code_agent";
  else if (needsTools && likelyParallelToolCalls && !complexMultiToolPlan)
    taskType = "tool_agent_parallel";
  else if (needsTools) taskType = "tool_agent";
  else if (multipleChoiceSignals >= 3) taskType = "reasoning_mcq";
  else if (compactMathProblem) taskType = "reasoning_math";
  else if (
    errorClassSignal ||
    /\b(?:bug|debug|error|failure|failing|regression|crash)\b|修复|报错|错误|调试/i.test(text)
  )
    taskType = "debug";
  else if (hasCode || /\b(?:refactor|implement|patch|edit|rewrite)\b|重构|实现|修改/i.test(text))
    taskType = "code_edit";
  else if (needsStructuredOutput || /\b(?:extract|json|schema|csv)\b|字段|提取/i.test(text))
    taskType = "extraction";
  else if (
    /\b(?:prove|derive|theorem|formal|mathematical|reasoning)\b|证明|推导|定理|数学/i.test(text)
  )
    taskType = "reasoning";

  return {
    taskType,
    estimatedInputTokens,
    hasCode,
    needsTools,
    toolsAvailable,
    needsVision,
    needsStructuredOutput,
    latencySensitive,
    highStakes,
    language,
    likelyParallelToolCalls,
    complexMultiToolPlan,
    agentDomain,
    deepWebResearch,
    agentRisk,
    terminalToolSignal,
    terminalSafetySensitive,
    implicitTerminalCode,
    codeArtifact,
  };
}

/**
 * Task-affinity bands. Each table maps a model name (the id after the
 * provider slash) to its calibrated affinity for one request shape; anything
 * absent scores the neutral `NEUTRAL_AFFINITY`. Names are matched exactly:
 * model family names are intentionally similar (`gemini-2.5-flash` vs
 * `gemini-2.5-flash-lite`), and a substring match would let a smaller sibling
 * inherit a capability claim measured only for the flagship. A sibling joins a
 * band only with its own evidence.
 */
type AffinityBand = Readonly<Record<string, number>>;

