/**
 * Recently added catalog models with a verified structured function call.
 *
 * Tool compliance is enough to make these models safe availability fallbacks,
 * but it is not evidence that they should displace a trajectory-benchmarked
 * primary. Keep them after the configured and benchmark-backed chains until a
 * full agent evaluation earns a task-specific affinity above NEUTRAL_AFFINITY
 * floor. `isEligible` still applies every host capability override, context
 * limit, vision constraint, and unavailable-model guard before they are used.
 */
const VERIFIED_TOOL_FALLBACKS = [
  "anthropic/claude-fable-5.1",
  "anthropic/claude-opus-5.5",
  "anthropic/claude-sonnet-5.5",
  "deepseek/deepseek-v4.1-flash",
  "google/gemini-3.8-flash",
  "openai/gpt-5.1",
  "openai/gpt-6-astra",
  "openai/gpt-6-luna",
  "openai/gpt-6-sol",
  "openai/gpt-6.1-sol",
  "xai/grok-4.6",
  "xai/grok-4.7",
  "xiaomi/mimo-v2.5",
] as const;

function isEligible(
  modelId: string,
  features: TaskFeatures,
  maxOutputTokens: number,
  options: RouterOptions,
): boolean {
  const model = options.modelCapabilities?.[modelId] ?? DEFAULT_MODEL_CAPABILITIES[modelId];
  // Preserve compatibility for temporarily catalog-less fallback IDs. They are
  // kept behind known-model candidates but are not silently dropped.
  if (!model) return true;
  if (features.needsTools && !model.supportsTools) return false;
  if (features.needsVision && !model.supportsVision) return false;
  if (features.needsStructuredOutput && !model.supportsTools) return false;
  if (model.maxOutputTokens < maxOutputTokens) return false;
  return model.contextWindow >= (features.estimatedInputTokens + maxOutputTokens) * 1.1;
}

function estimatedCost(
  modelId: string,
  options: RouterOptions,
  inputTokens: number,
  outputTokens: number,
): number {
  const price = usablePricing(options.modelPricing.get(modelId));
  if (!price) return Number.POSITIVE_INFINITY;
  if (price.flatPrice !== undefined) return price.flatPrice;
  return (inputTokens * price.inputPrice + outputTokens * price.outputPrice) / 1_000_000;
}

function profileScore(
  modelId: string,
  options: RouterOptions,
  now: Date,
):
  | { quality?: number; speed: number; tailSpeed: number; reliability: number; freshness: number }
  | undefined {
  const profile: ModelPerformanceProfile | undefined =
    options.modelPerformance?.[modelId] ??
    LIVE_MODEL_PROFILES[modelId] ??
    HISTORICAL_MODEL_PROFILES[modelId];
  if (!profile) return undefined;
  const measuredAt = Date.parse(profile.measuredAt);
  if (!Number.isFinite(measuredAt)) return undefined;
  // A host-injected observation with a missing or non-numeric field would
  // turn the whole score into NaN, and NaN compares as "equal" in the sort,
  // freezing that candidate wherever it landed. Treat it as no observation.
  const finite = (value: number | undefined, optional: boolean) =>
    value === undefined ? optional : Number.isFinite(value) && value >= 0;
  if (
    !finite(profile.latencyMs, false) ||
    !finite(profile.outputTokensPerSecond, false) ||
    !finite(profile.p95LatencyMs, true) ||
    !finite(profile.intelligenceIndex, true) ||
    !finite(profile.errorRate, true) ||
    !finite(profile.samples, true)
  ) {
    return undefined;
  }
  const ageDays = Math.max(0, (now.getTime() - measuredAt) / 86_400_000);
  // A 30-day half-life makes old data a tie-breaker only. Small probe runs are
  // also weak evidence: three quick samples should not overturn a curated
  // tier ordering merely because of a transient provider tail. Callers that
  // inject an observation without a sample count retain the legacy full
  // confidence behaviour for compatibility.
  const sampleConfidence =
    profile.samples === undefined ? 1 : Math.min(1, Math.max(0, profile.samples) / 10);
  const freshness = Math.pow(0.5, ageDays / 30) * sampleConfidence;
  const quality =
    profile.intelligenceIndex === undefined
      ? undefined
      : Math.min(1, profile.intelligenceIndex / 50);
  const speed = Math.min(
    1,
    (2_000 / Math.max(500, profile.latencyMs) + profile.outputTokensPerSecond / 250) / 2,
  );
  const tailSpeed = Math.min(1, 3_000 / Math.max(750, profile.p95LatencyMs ?? profile.latencyMs));
  const reliability = Math.max(0, 1 - (profile.errorRate ?? 0));
  return { quality, speed, tailSpeed, reliability, freshness };
}

/** Candidate router used for Auto. Rules still set the capability tier; V3 ranks within it. */
export class PortfolioStrategy implements RouterStrategy {
  readonly name = "portfolio";
  // Rules set the capability tier; the strategy is stateless, so one instance serves every request.
  private readonly rules = new RulesStrategy();

  route(
    prompt: string,
    systemPrompt: string | undefined,
    maxOutputTokens: number,
    options: RouterOptions,
  ) {
    const features = classifyTask(prompt, systemPrompt, options);
    const base = this.rules.route(prompt, systemPrompt, maxOutputTokens, {
      ...options,
      requiresTools: features.needsTools,
    });
    const tierConfigs = base.tierConfigs;
    if (!tierConfigs) return base;
    // The rules score sets the capability tier, but two task types carry a
    // floor of their own: a compact reasoning problem belongs on the
    // reasoning chain however short it is, and a code edit or stack trace
    // belongs at least on the MEDIUM chain — the SIMPLE chain is curated for
    // trivia and translation and has no model with code affinity. The code
    // floor requires a code artifact or coding action: `debug` and `code_edit`
    // are also assigned from bare verbs ("rewrite this sentence", "margin of
    // error") and bare language names ("What is Python?"), and that prose
    // must stay on the cheap chain.
    const targetTier: Tier =
      (features.taskType === "reasoning_mcq" || features.taskType === "reasoning_math") &&
      (base.tier === "SIMPLE" || base.tier === "MEDIUM")
        ? "REASONING"
        : (features.taskType === "debug" || features.taskType === "code_edit") &&
            features.codeArtifact &&
            base.tier === "SIMPLE"
          ? "MEDIUM"
          : base.tier;
    const tierConfig = tierConfigs[targetTier];
    const configuredCandidates = tierConfig ? getFallbackChain(targetTier, tierConfigs) : [];
    // Evidence candidates join the configured chain, but the host's
    // unavailable set applies to both: the configured side arrives filtered
    // through RulesStrategy, and a dead evidence model must not re-enter here.
    const unavailable = new Set(options.unavailableModels ?? []);
    // `modelPricing` is the host's live catalog view. Do not introduce a
    // built-in fallback that the current gateway does not advertise. These
    // models carry no task evidence, so outside Premium the cheapest one is
    // the first recovery hop; otherwise an outage of the curated chain would
    // jump an Eco turn straight to the most expensive model in the list.
    const verifiedToolFallbacks = features.needsTools
      ? VERIFIED_TOOL_FALLBACKS.filter((model) => options.modelPricing.has(model))
      : [];
    if (options.routingProfile !== "premium") {
      const fallbackCost = (model: string) =>
        estimatedCost(model, options, features.estimatedInputTokens, maxOutputTokens);
      verifiedToolFallbacks.sort((a, b) => fallbackCost(a) - fallbackCost(b));
    }
    const chain = [
      ...new Set([
        ...configuredCandidates,
        ...evidenceCandidates(features.taskType),
        ...verifiedToolFallbacks,
      ]),
    ].filter(
      (model): model is string =>
        typeof model === "string" && model.length > 0 && !unavailable.has(model),
    );
    const eligible = new Set(
      chain.filter((model) => isEligible(model, features, maxOutputTokens, options)),
    );
    // When nothing is eligible the whole chain competes, scored as incapable.
    const eligibleCandidates = eligible.size > 0 ? [...eligible] : chain;
    if (eligibleCandidates.length === 0) return base;
    const profileName =
      options.routingProfile === "eco"
        ? "eco"
        : options.routingProfile === "premium"
          ? "premium"
          : "auto";
    const portfolio = options.config.portfolio ?? DEFAULT_PORTFOLIO_WEIGHTS;
    const band = affinityBand(features);
    const affinityCache = new Map<string, number>();
    const getAffinity = (model: string) => {
      let value = affinityCache.get(model);
      if (value === undefined) {
        value = affinityIn(band, model);
        affinityCache.set(model, value);
      }
      return value;
    };
    const bestAffinity = Math.max(...eligibleCandidates.map(getAffinity));
    const specificAffinity = eligibleCandidates.filter((model) => getAffinity(model) > NEUTRAL_AFFINITY);
    // A tier's fallback list is primarily an availability/recovery chain, not a
    // set of equally validated substitutes.  Re-ranking every fallback lets a
    // cheap generic model displace the curated primary merely because it has a
    // favourable short performance probe.  Only promote models with explicit
    // task affinity; otherwise retain the first capability-eligible tier model.
    const affinityPool = specificAffinity.length > 0 ? specificAffinity : [eligibleCandidates[0]];
    // Generic Terminal work has much wider trajectory variance than a BFCL-like
    // one-turn parallel call. Keep the strong-model safety band, but admit the
    // next capable tier so Auto's cost/reliability score can reject an Opus
    // primary that is materially more expensive without measured benefit.
    const affinityFloorGap = features.terminalToolSignal
      ? Math.max(
          portfolio.affinityFloorGap[profileName],
          features.terminalSafetySensitive ? 0.15 : 0.12,
        )
      : portfolio.affinityFloorGap[profileName];
    const candidates = affinityPool.filter(
      (model) => getAffinity(model) >= bestAffinity - affinityFloorGap,
    );
    const costs = candidates.map((model) =>
      estimatedCost(model, options, features.estimatedInputTokens, maxOutputTokens),
    );
    const finiteCosts = costs.filter(Number.isFinite);
    const minCost = finiteCosts.length > 0 ? Math.min(...finiteCosts) : 0;
    const maxCost = finiteCosts.length > 0 ? Math.max(...finiteCosts) : 1;

    const now = options.now ?? new Date();
    const profileWeights = portfolio[profileName];
    const rankedEntries = candidates
      .map((model, index) => {
        const cost = costs[index];
        // An unpriced candidate costs an unknown amount, so it scores as the
        // most expensive rather than a neutral 0.5 that let it outrank
        // priced models. Pricing presence still never filters a candidate.
        const costScore = !Number.isFinite(cost)
          ? 0
          : maxCost > minCost
            ? 1 - (cost - minCost) / (maxCost - minCost)
            : 0.5;
        const capabilityScore = eligible.has(model) ? 1 : 0;
        const profile = profileScore(model, options, now);
        // Fresh observations can refine affinity. Historical observations fade
        // quickly and never replace task-level RouterBench evidence.
        const observedQuality =
          profile?.quality === undefined
            ? getAffinity(model)
            : getAffinity(model) * (1 - profile.freshness) + profile.quality * profile.freshness;
        // Every observed dimension fades toward its neutral prior as the
        // observation ages, exactly like reliability below. Fading speed
        // toward zero instead ranked any model with a stale probe below a
        // model nobody had measured, which the latter's 0.5 silently won.
        const observedSpeed = profile
          ? profile.speed * profile.freshness + 0.5 * (1 - profile.freshness)
          : 0.5;
        const observedTailSpeed = profile
          ? profile.tailSpeed * profile.freshness + 0.5 * (1 - profile.freshness)
          : 0.5;
        const observedReliability = profile
          ? profile.reliability * profile.freshness + (1 - profile.freshness)
          : 1;
        // Preserve a small amount of the hand-curated fallback order while V3's
        // task affinity and real request constraints do the primary work.
        const legacyScore = 1 - index / Math.max(1, candidates.length - 1);
        const qualityWeight =
          profileWeights.quality + (features.highStakes ? portfolio.highStakesBoost.quality : 0);
        const speedScore = features.latencySensitive ? observedTailSpeed : observedSpeed;
        const speedWeight =
          profileWeights.speed +
          (features.latencySensitive ? portfolio.latencySensitiveSpeedBoost : 0);
        const reliabilityWeight =
          profileWeights.reliability +
          (features.highStakes ? portfolio.highStakesBoost.reliability : 0);
        const score =
          observedQuality * qualityWeight +
          capabilityScore * profileWeights.capability +
          costScore * profileWeights.cost +
          speedScore * speedWeight +
          observedReliability * reliabilityWeight +
          legacyScore * profileWeights.legacy;
        return {
          model,
          score,
          quality: observedQuality,
          cost: costScore,
          speed: speedScore,
          reliability: observedReliability,
        };
      })
      .sort((a, b) => b.score - a.score);
    const scoredModels = rankedEntries.map((item) => item.model);
    // The affinity floor controls which models may compete for the primary;
    // it must not erase availability fallbacks. Append all remaining eligible
    // models in their curated chain order after the scored primary pool.
    const webResearchFallbackOrder = [
      "anthropic/claude-sonnet-5",
      "openai/gpt-5-mini",
      "google/gemini-3.5-flash",
      "anthropic/claude-opus-5",
      "anthropic/claude-opus-4.8",
      "openai/gpt-5.3-codex",
    ];
    const ranked =
      features.agentDomain === "web_research"
        ? [
            ...scoredModels,
            ...webResearchFallbackOrder.filter(
              (model) => eligibleCandidates.includes(model) && !scoredModels.includes(model),
            ),
            ...eligibleCandidates.filter(
              (model) => !scoredModels.includes(model) && !webResearchFallbackOrder.includes(model),
            ),
          ]
        : [...scoredModels, ...eligibleCandidates.filter((model) => !scoredModels.includes(model))];

    const model = ranked[0] ?? base.model;
    const selectedTierConfigs: Record<Tier, TierConfig> = {
      ...tierConfigs,
      [targetTier]: { primary: model, fallback: ranked.slice(1) },
    };
    // selectModel only reads the selected tier; retain the complete tier map for host fallback.
    const decision = selectModel(
      targetTier,
      base.confidence,
      "portfolio",
      `${base.reasoning} | v3 task=${features.taskType} agentRisk=${features.agentRisk} deepWebResearch=${features.deepWebResearch} terminalCode=${features.implicitTerminalCode} terminalSafety=${features.terminalSafetySensitive} candidates=${ranked.length}`,
      selectedTierConfigs,
      options.modelPricing,
      features.estimatedInputTokens,
      maxOutputTokens,
      options.routingProfile,
      base.agenticScore,
    );
    return {
      ...decision,
      tierConfigs: selectedTierConfigs,
      profile: base.profile,
      candidates: ranked,
      candidateScores: rankedEntries.map(({ model, score, quality, cost, speed, reliability }) => ({
        model,
        score,
        quality,
        cost,
        speed,
        reliability,
      })),
      taskType: features.taskType,
      routerVersion: "v3-portfolio" as const,
    };
  }
}
